script:
suppressPackageStartupMessages({
  library(readxl)
  library(ggplot2)
  library(ggVennDiagram)
  library(showtext)
})
# Try to register a CJK font if available; fall back gracefully otherwise
font_ok <- tryCatch({
  showtext_auto()
  cands <- c(
    "Noto Sans CJK SC", "Noto Sans CJK JP", "Source Han Sans CN",
    "Source Han Sans SC", "WenQuanYi Micro Hei", "Sarasa Gothic SC",
    "PingFang SC", "Heiti SC", "STHeiti", "SimHei", "Microsoft YaHei"
  )
  picked <- NULL
  for (f in cands) {
    if (f %in% systemfonts::registry_fonts()$family) { picked <- f; break }
  }
  if (is.null(picked)) {
    # Search by pattern as a fallback
    sysfonts_avail <- systemfonts::registry_fonts()$family
    hit <- grep("cjk|noto|han|sc|chinese|hei|pingfang|wqy", sysfonts_avail,
                ignore.case = TRUE, value = TRUE)
    if (length(hit) > 0) picked <- hit[1]
  }
  if (!is.null(picked)) {
    showtext_opts(dpi = 200)
    cat("Using CJK font:", picked, "\n")
    TRUE
  } else {
    cat("No CJK font found; using English title fallback.\n")
    FALSE
  }
}, error = function(e) FALSE)
title_text <- if (font_ok) "Synthetic Venn diagram (5 groups, A–E)" else "Proportional Venn Diagram (5 sets, A–E)"
subtitle_text <- if (font_ok) {
  sprintf("Set sizes: A=%d, B=%d, C=%d, D=%d, E=%d",
          80L, 58L, 62L, 56L, 125L)
} else {
  sprintf("Set sizes: A=%d, B=%d, C=%d, D=%d, E=%d", 80L, 58L, 62L, 56L, 125L)
}
fp <- "inputs/set-membership-111111111111.xlsx"
df <- read_excel(fp, sheet = "5 groups")
sets <- lapply(df, function(x) unique(na.omit(as.character(x))))
p <- ggVennDiagram(
  sets,
  label_alpha    = 0,
  label_geom     = "label",
  set_color      = c("#4DAF4A", "#377EB8", "#E41A1C", "#984EA3", "#FF7F00"),
  set_size       = 3,
  category_size  = 4.5,
  show_intersections = TRUE
) +
  scale_fill_gradient(low = "white", high = "#377EB8") +
  scale_x_continuous(expand = expansion(mult = 0.1)) +
  scale_y_continuous(expand = expansion(mult = 0.1)) +
  labs(
    title    = title_text,
    subtitle = subtitle_text,
    fill     = "Region size"
  ) +
  theme(
    plot.title    = element_text(face = "bold", hjust = 0.5),
    plot.subtitle = element_text(hjust = 0.5, color = "grey30")
  )
out_png <- "proportional_venn_5sets.png"
ggsave(out_png, p, width = 9, height = 7, dpi = 200, bg = "white")
cat("Saved:", out_png, "size=", file.info(out_png)$size, "bytes\n")

suppressPackageStartupMessages({
  library(showtext)
  library(sysfonts)
})
# Try to register a CJK font available on the system.
# showtext can load any system font by family name from fontconfig.
font_ok <- tryCatch({
  showtext_auto(enable = TRUE)
  showtext_opts(dpi = 200)
  candidates <- c(
    "Noto Sans CJK SC", "Noto Sans CJK JP", "Source Han Sans CN",
    "Source Han Sans SC", "WenQuanYi Micro Hei", "PingFang SC",
    "Heiti SC", "STHeiti", "SimHei", "Microsoft YaHei",
    "Songti SC", "STSong", "Hiragino Sans GB"
  )
  picked <- NULL
  for (f in candidates) {
    ok <- tryCatch({ sysfonts::font_add(family = f, regular = f); TRUE },
                   error = function(e) FALSE)
    if (ok) { picked <- f; break }
  }
  if (!is.null(picked)) {
    cat("CJK font registered:", picked, "\n")
    TRUE
  } else {
    cat("No CJK font registered; using English title.\n")
    FALSE
  }
}, error = function(e) {
  cat("showtext setup failed:", conditionMessage(e), "\n")
  FALSE
})
title_text <- if (font_ok) "Synthetic Venn diagram (5 groups, A–E)" else "Proportional Venn Diagram (5 sets, A–E)"
subtitle_text <- if (font_ok) {
  sprintf("Set sizes: A=80, B=58, C=62, D=56, E=125")
} else {
  sprintf("Set sizes: A=80, B=58, C=62, D=56, E=125")
}
font_family <- if (font_ok) candidates[match(picked, candidates)] else ""
suppressPackageStartupMessages({
  library(readxl)
  library(ggplot2)
  library(ggVennDiagram)
})
fp <- "inputs/set-membership-111111111111.xlsx"
df <- read_excel(fp, sheet = "5 groups")
sets <- lapply(df, function(x) unique(na.omit(as.character(x))))
p <- ggVennDiagram(
  sets,
  label_alpha    = 0,
  label_geom     = "label",
  set_color      = c("#4DAF4A", "#377EB8", "#E41A1C", "#984EA3", "#FF7F00"),
  set_size       = 3,
  category_size  = 4.5,
  show_intersections = TRUE
) +
  scale_fill_gradient(low = "white", high = "#377EB8") +
  scale_x_continuous(expand = expansion(mult = 0.1)) +
  scale_y_continuous(expand = expansion(mult = 0.1)) +
  labs(
    title    = title_text,
    subtitle = subtitle_text,
    fill     = "Region size"
  ) +
  theme(
    plot.title    = element_text(face = "bold", hjust = 0.5, family = font_family),
    plot.subtitle = element_text(hjust = 0.5, color = "grey30", family = font_family)
  )
out_png <- "proportional_venn_5sets.png"
ggsave(out_png, p, width = 9, height = 7, dpi = 200, bg = "white")
cat("Saved:", out_png, "size=", file.info(out_png)$size, "bytes\n")
